create function public.report_conduct(p_match uuid,p_reason text,p_description text) returns uuid language plpgsql security definer set search_path=public as $$ declare m public.matches; me uuid:=auth.uid(); result uuid; begin if me is null then raise exception 'Sign in to report conduct.'; end if; select * into m from public.matches where id=p_match and me in(user1,user2); if m.id is null then raise exception 'Access denied.'; end if; if p_reason is null or p_reason not in ('inappropriate-behavior','harassment','spam','fake-profile','other') then raise exception 'Select a valid reason.'; end if; if char_length(coalesce(p_description,''))>1000 then raise exception 'Report details must be 1000 characters or fewer.'; end if; perform pg_advisory_xact_lock(hashtextextended(me::text,1)); if exists(select 1 from public.reports where reported_by=me and match_id=p_match and created_at>now()-interval '1 minute') then raise exception 'Your recent report was received. Please wait before sending another.'; end if; insert into public.reports(reported_user,reported_by,match_id,reason,description) values(case when m.user1=me then m.user2 else m.user1 end,me,p_match,p_reason,nullif(btrim(p_description),'')) returning id into result; return result; end $$; revoke all on function public.report_conduct(uuid,text,text) from public,anon; grant execute on function public.report_conduct(uuid,text,text) to authenticated; revoke insert on public.reports from authenticated; grant select on public.reports to authenticated; create policy "read own submitted reports" on public.reports for select to authenticated using(reported_by=auth.uid());